"""Explicit corrections of existing catalogue entries, not model-generated recipes.

Dry cereals and edible ingredients are weighed before preparation unless the
ingredient name explicitly says cooked. Water used for boiling is in the method.
"""
from .nutrition import calculate_nutrition


def entry(name, ingredients, minutes, diet, allergens, steps, slot="breakfast"):
    return {"name": name, "ingredients": ingredients, **calculate_nutrition(ingredients),
            "preparation_minutes": minutes, "diet": diet, "allergens": allergens,
            "instructions": "\n".join(f"{i + 1}. {step}" for i, step in enumerate(steps)),
            "meal_slot": slot, "side_dish": "", "batch_servings": 1, "storage_days": 0,
            "nutrition_status": "ingredient_estimate", "nutrition_source": "USDA SR Legacy 2018; расчёт по ингредиентам",
            "weight_basis": "ingredients_before_cooking"}


